create or replace TABLE LDL_PRODUCTION_CLONE_GOOGLE_20260608_1030.P_LEW_CORE.T_ITEM_INFO_PER_LOCATION_HIST_2 (
	CLIENT_ID NUMBER(38,0) NOT NULL COMMENT 'DWH-Mandant_2; FK auf CLIENT',
	ITEM_SID NUMBER(38,0) NOT NULL COMMENT 'Item_2',
	LOC_SID NUMBER(38,0) NOT NULL COMMENT 'Store / WH',
	ITEM_STATUS_ID NUMBER(38,0),
	ORDER_AREA_SID NUMBER(38,0) COMMENT 'surrogate key; uniquely identifies a WH Order Area',
	PUR_GRP_SID NUMBER(38,0) COMMENT 'responsible purchase group for the item_2',
	ITEM_STATUS_CD VARCHAR(20) COMMENT 'location_2 specific item_2 status_2; SAP-Retail: marc.mmsta;',
	ITEM_STATUS_ACTIVE_FROM_DT DATE COMMENT 'date when the item_2 status_2 became active; SAP-Retail: marc.mmstd;',
	CASE_SIZE_DEC_QTY NUMBER(9,5) COMMENT 'how many pieces / how much weight are/is grouped to one case',
	EURO_PALLET_FACTOR_QTY NUMBER(9,5) COMMENT 'how many cases do fit onto a Euro-Pallet',
	DD_PALLET_FACTOR_QTY NUMBER(9,5) COMMENT 'how many cases do fit onto a Dusseldorf-Pallet',
	LAYER_FACTOR_QTY NUMBER(9,5) COMMENT 'how many cases do fit onto one layer of a Euro-Pallet',
	PALLET_FACTOR NUMBER(18,5) COMMENT 'Palettenfaktor; berechnet bei der Extraktion durch SAP-BW: t_bw_0art_plant_attr/t_bw_z_ds_mxxd2016.zzev_pal_fak;',
	PALLET_FACTOR_DUS NUMBER(18,5) COMMENT 'Duesseldorfer Palettenfaktor; berechnet bei der Extraktion durch SAP-BW: t_bw_0art_plant_attr/t_bw_z_ds_mxxd2016.zzv_dus_fakt;',
	PALLET_FACTOR_GMA NUMBER(18,5) COMMENT 'GMA Palettenfaktor; SAP-BW: t_bw_z_ds_mxxd2016.zkgmafakt;',
	CASE_FACTOR NUMBER(18,5) COMMENT 'Kollifaktor; berechnet bei der Extraktion durch SAP-BW: t_bw_0art_plant_attr/t_bw_z_ds_mxxd2016.zzev_kol_fakt;',
	SHELFLIFE_CUST_CD VARCHAR(20) COMMENT 'Restlaufzeit Kunde - Einheit: T=Tag_2, W=Woche_2, M=Monat_2, J=Jahr; SAP-Retail: marc.zz_rlzkm; SAP-BW: t_bw_0art_plant_attr.zz_rlzkm;',
	SHELFLIFE_CUST_VAL NUMBER(18,5) COMMENT 'Restlaufzeit Kunde - Wert; SAP-Retail: marc.zz_rlzk; SAP-BW: t_bw_0art_plant_attr.zz_rlzk;',
	SHELFLIFE_LOC_CD VARCHAR(20) COMMENT 'Restlaufzeit Filiale - Einheit: T=Tag_2, W=Woche_2, M=Monat_2, J=Jahr; SAP-Retail: marc.zz_rlzfm; SAP-BW: t_bw_0art_plant_attr.zz_rlzfm;',
	SHELFLIFE_LOC_VAL NUMBER(18,5) COMMENT 'Restlaufzeit Filiale - Wert; SAP-Retail: marc.zz_rlzf; SAP-BW: t_bw_0art_plant_attr.zz_rlzf;',
	SHELFLIFE_VZ_CD VARCHAR(20) COMMENT 'Restlaufzeit Betrieb - Einheit: T=Tag_2, W=Woche_2, M=Monat_2, J=Jahr; SAP-Retail: marc.zz_rlzbm; SAP-BW: t_bw_0art_plant_attr.zz_rlzbm;',
	SHELFLIFE_VZ_VAL NUMBER(18,5) COMMENT 'Restlaufzeit Betrieb - Wert; SAP-Retail: marc.zz_rlzb; SAP-BW: t_bw_0art_plant_attr.zz_rlzb;',
	REPLENISHMENT_TYPE_CD VARCHAR(20) COLLATE 'en-ci' COMMENT 'Dispositionsmerkmal; SAP-Retail: marc.dismm;',
	REPLENISHMENT_PLANNER_CD VARCHAR(20) COLLATE 'en-ci' COMMENT 'Disponent; SAP-Retail: marc.dispo;',
	PROCUREMENT_TYPE_CD VARCHAR(20) COLLATE 'en-ci' COMMENT 'Beschaffungsart; E=Eigenfertigung; F=Fremdbeschaffung; X=beide Beschaffungsarten; SAP-Retail: marc.beskz; SAP-BW: t_bw_0art_plant_attr.beskz;',
	SOURCE_OF_SUPPLY_CD VARCHAR(20) COLLATE 'en-ci' COMMENT 'Bezugsquelle, 1=Normal, 2=Umlagerung_2, ... siehe SAP-Retail-Ref.-Tab TMBW1; SAP-Retail: marc.bwscl; SAP-BW: t_bw_0art_plant_attr.bwscl;',
	ROUNDING_PROFILE_CD VARCHAR(20) COLLATE 'en-ci' COMMENT 'Rundungsprofil, ...siehe SAP-Retail-Ref.-Tab RDPR; SAP-Retail marc.rdprf; SAP-BW: t_bw_0art_plant_attr.rdprf;',
	STOCK_MAX_QTY NUMBER(18,5) COMMENT 'Hoechstbestand; SAP-Retail: -; SAP-BW: t_bw_0art_plant_attr.zzmabst;',
	ORDER_MIN_QTY NUMBER(18,5) COMMENT 'Mindestlosgroesse; SAP-Retail: ; SAP-BW: t_bw_0art_plant_attr.zzbstmi;',
	TARGET_RANGE_MIN_QTY NUMBER(18,5) COMMENT 'Minimale Sollreichweite; SAP-Retail: marc.min_troc; SAP-BW: t_bw_0art_plant_attr.min_troc;',
	TARGET_RANGE_MAX_QTY NUMBER(18,5) COMMENT 'Maximale Sollreichweite; SAP-Retail: marc.max_troc; SAP-BW: t_bw_0art_plant_attr.max_troc;',
	ITEM_MARKED_FOR_DELETION_FG NUMBER(38,0) COMMENT 'Artikel_2 auf Betriebsebene zum Loeschen vormerken; SAP-Retail: marc.lvorm; SAP-BW: t_bw_0art_plant_attr.lvorm;',
	DELETED_FG NUMBER(38,0) NOT NULL COMMENT 'Artikel_2-Lokation-Bez. ist im Falle deleted_fg = 1 im Zeitraum dwh_valid_from / dwh_valid_to nicht im Quellsystem bekannt; Hinweis: auch bei gesetztem Loeschkz im Quellsystem wird dieser Status_2 angenommen',
	DWH_VALID_FROM DATE NOT NULL COMMENT 'Gueltigkeitsbeginn; Teil der DWH-Historisierung; aeltester Satz der Historie erhaelt immer den Wert 01.01.1900 (\""minus unendlich\"")',
	DWH_VALID_TO DATE NOT NULL COMMENT 'Gueltigkeitsende; Teil der DWH-Historisierung; neuster Satz der Historie erhaelt immer den Wert 30.12.9999 (\""plus unendlich\"")',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'Identifier des letzten Ladelaufs, der den Datensatz eingfuegt oder veraendert hat',
	DWH_CREATED TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Zeitstempel der Ersteinfuegung des Datensatzes ins DWH',
	DWH_UPDATED TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Zeitstempel der letzten Aenderung des Datensatzes im DWH',
	constraint PK_T_ITEM_INFO_PER_LOCATION_HIST primary key (ITEM_SID, LOC_SID, DWH_VALID_FROM)
)COMMENT='$Revision: 0000 $. Information regarding Items in relation to a certain Store or Warehouse;\n             SAP-Retail: marc_2;\n             SAP-BW: t_bw_0art_plant_attr;\n             WAWI: t_itm_item_wh\n             '
;
